INSERT INTO public.community_feedback (type, status, context_query, context_persona, email, message, faq_question, faq_answer)
SELECT 'duvida', 'publicado', NULL, NULL, NULL, q, q, a
FROM (VALUES
('O que é o Motor da Inovação?', 'É uma infraestrutura computacional pública, desenvolvida como parte de uma tese de doutorado em Políticas Públicas na UFPR, que conecta Pesquisa, Produção, Política e Patentes (4P) no sistema de inovação brasileiro. Dado um tema ou objeto tecnológico, ele constrói automaticamente um panorama com dados de mais de 30 bases públicas.'),
('Quem pode usar o Motor e para quê?', 'Existem 4 perspectivas (personas): Pesquisador (o que já existe sobre o tema, quem pesquisa, onde buscar financiamento), Universidade (como a instituição se posiciona e onde captar recursos), Empresa (se vale entrar no mercado, quanto custa inovar, quem pode ajudar) e Governo (se o tema merece política pública e qual instrumento cabe).'),
('O Motor cobra alguma coisa para usar?', 'Não. É um projeto de pesquisa acadêmica e todas as fontes de dados consultadas são públicas e gratuitas.'),
('O código é realmente aberto? Onde vejo o repositório?', 'Sim, é um projeto 100% open source sob licença MIT. O repositório inclui backend, frontend, conectores de dados e modelos analíticos, com documentação de arquitetura (ARCHITECTURE.md) e guia de contribuição (CONTRIBUTING.md).'),
('O que é o índice GT (Gap de Tradução)?', 'Mede a distância entre a produção científica de um tema e sua aplicação tecnológica real (patentes, contratos, código aberto). É calculado como log10(papers científicos / sinais de aplicação) — quanto mais papers e menos aplicação prática, maior o gap.'),
('O que é o índice CD (Dependência Científica)?', 'Mede o percentual da produção científica sobre o tema que tem origem fora do Brasil, com base em coautorias internacionais registradas no OpenAlex. Quanto maior, mais o campo depende de conhecimento produzido no exterior.'),
('O que é o índice AUE (Articulação Universidade-Empresa)?', 'Um score composto que soma sinais de conexão entre academia e mercado: existência de base científica, instrumentos públicos (contratos/convênios), código aberto com tração, rede internacional de coautoria e financiamento identificado nos papers.'),
('O que é o índice EI (Efetividade Instrumental)?', 'Mede o alinhamento entre a maturidade tecnológica do tema (TRL) e a intensidade dos instrumentos públicos disponíveis (valor e quantidade de contratos/convênios). Um TRL alto sem instrumentos correspondentes, ou vice-versa, reduz a efetividade.'),
('Por que às vezes um índice aparece com "confiança baixa"?', 'Porque o cálculo depende da quantidade de dados encontrados. Quando há poucos sinais (poucos papers, nenhum contrato, TRL estimado por poucos critérios), o Motor sinaliza isso explicitamente em vez de apresentar um número com falsa precisão.'),
('Os índices são comparáveis entre temas diferentes?', 'Com cautela. Os índices usam a mesma fórmula para qualquer tema, mas campos com poucos dados disponíveis (ex: temas de nicho) terão índices menos confiáveis do que campos bem documentados nas bases públicas — a comparação deve sempre considerar o nível de confiança indicado.'),
('Como o Motor entende o que eu digitei na busca?', 'Um motor de ontologia traduz o termo livre digitado em códigos oficiais: CNAE (atividade econômica), NCM (comércio exterior), IPC (patentes) e áreas do CNPq (classificação científica), usando um dicionário curado de termos e sinônimos.'),
('O que é CNAE e por que aparece na minha busca?', 'CNAE é a Classificação Nacional de Atividades Econômicas — o código que o governo usa para identificar o setor de uma empresa. O Motor usa o CNAE para buscar dados econômicos (emprego, contratos, PIB setorial) relacionados ao tema.'),
('O que é NCM?', 'Nomenclatura Comum do Mercosul — o código usado em notas fiscais e no comércio exterior. Serve para consultar dados de importação e exportação do produto relacionado ao tema (COMEX Stat).'),
('O que é IPC?', 'Classificação Internacional de Patentes — usada para buscar patentes nacionais e internacionais relacionadas ao tema, e para estimar o TRL (maturidade tecnológica) a partir de dados reais de patenteamento.'),
('O que é área CNPq, e quando ela aparece no lugar do CNAE?', 'São as áreas oficiais de conhecimento científico do CNPq (ex: Engenharia Química, Física). Quando o tema pesquisado é uma disciplina científica transversal — que não corresponde a uma única atividade econômica, como "reologia", que se aplica a petróleo, alimentos, cosméticos e outros setores — o Motor mostra as áreas CNPq como classificação de referência em vez de forçar um CNAE único.'),
('Por que às vezes nenhuma classificação é encontrada?', 'O dicionário de tradução é curado e cresce conforme casos reais são identificados; termos muito específicos ou fora do escopo industrial/científico mapeado ainda podem não ter correspondência. Isso não impede a busca de continuar — outras camadas (como produção científica) não dependem dessa classificação.'),
('De onde vêm os artigos científicos mostrados?', 'Do OpenAlex, o maior repositório aberto de artigos científicos do mundo (mais de 240 milhões de registros), incluindo instituições, coautorias internacionais e financiadores extraídos dos metadados dos papers.'),
('De onde vêm os dados de contratos e licitações públicas?', 'Do PNCP (Portal Nacional de Contratações Públicas) e do Portal da Transparência do Governo Federal (convênios, emendas parlamentares).'),
('De onde vêm os dados de emprego formal?', 'Do Novo CAGED (Cadastro Geral de Empregados e Desempregados), via IPEAData — cobre apenas empregos com carteira assinada; autônomos e informais não estão incluídos, e o recorte por CNAE específico não está disponível em API pública (só por seção CNAE ou UF).'),
('De onde vêm os dados de patentes?', 'Do EPO (European Patent Office) e de bases públicas do INPI, usados também para estimar o TRL real da tecnologia.'),
('De onde vêm os dados econômicos (PIB, orçamento)?', 'PIB municipal e setorial vêm do IBGE/SIDRA. Orçamento e execução fiscal de estados e municípios vêm do SICONFI (Tesouro Nacional).'),
('De onde vêm as menções em diário oficial?', 'Do Querido Diário, que indexa diários oficiais municipais — permite localizar editais, chamadas e licitações mencionando o tema pesquisado.'),
('De onde vêm as informações sobre tramitação de leis?', 'Dos Dados Abertos da Câmara dos Deputados e do Senado Federal — proposições legislativas relacionadas ao tema pesquisado.'),
('Todos os dados são atualizados em tempo real?', 'A maioria das camadas consulta as APIs públicas ao vivo, a cada busca. Exceções documentadas: os números do ecossistema de inovação (ANPROTEC) na aba Políticas são estáticos e revisados periodicamente, não uma consulta viva.'),
('O que é a Visão Regional e como ativo ela?', 'É uma aba disponível nas 4 perspectivas que mostra PIB municipal, orçamento da prefeitura, menções no Diário Oficial local, instituições de pesquisa e empresas do setor na sua cidade. Para vê-la, selecione um estado e município antes de pesquisar.'),
('Por que alguns dados regionais aparecem como indisponíveis?', 'O Motor mostra o motivo explícito em vez de omitir a informação — por exemplo, convênios federais recebidos pelo município dependem de uma chave de acesso ao Portal da Transparência que pode não estar configurada, ou um município pequeno pode simplesmente não ter dado publicado em uma fonte específica.'),
('O que é o gráfico de evolução dos índices?', 'A cada busca, o Motor grava os valores dos índices GT/CD/AUE/EI daquele tema. Quando você pesquisa o mesmo tema mais de uma vez (em datas diferentes), um gráfico de linha mostra como esses índices mudaram ao longo do tempo.'),
('Por que meu tema não tem histórico ainda?', 'Porque é a primeira vez que esse tema específico é registrado no Motor. A partir da próxima vez que alguém pesquisar o mesmo termo, o histórico começa a aparecer.'),
('O Motor pode errar a classificação do meu tema?', 'Sim — a tradução de termo para CNAE/NCM/IPC/CNPq é uma heurística curada manualmente, não uma correspondência perfeita. Termos muito específicos, ambíguos ou novos podem receber uma classificação imprecisa ou nenhuma.'),
('A análise de IA (aba "Análise IA") é confiável?', 'É uma síntese gerada automaticamente a partir dos dados coletados nas outras camadas — útil como ponto de partida, mas deve ser lida como uma interpretação, não como fato verificado. Sempre confira os dados brutos nas outras abas.'),
('Como eu sugiro uma melhoria ou aponto um erro?', 'Use o formulário nesta própria página de FAQ (/faq) — escolha o tipo (dúvida, correção de dado ou sugestão) e envie sua mensagem. E-mail é opcional, só necessário se você quiser resposta.'),
('Como eu contribuo com código?', 'O repositório é público sob licença MIT. Consulte o CONTRIBUTING.md no repositório para o passo a passo de configuração do ambiente (backend Python, frontend React, Edge Functions do Supabase) e o padrão para propor um novo conector de dados.')
) AS seed(q, a);